select case when unit_price >= 340 then 'high' when unit_price >= 110 then 'mid' else 'low' end as unit_price_bucket, product_id, round(stddev(quantity), 2) as stddev_quantity, count(*) as row_count from order_items group by case when unit_price >= 340 then 'high' when unit_price >= 110 then 'mid' else 'low' end, product_id having row_count < 2 order by stddev_quantity, unit_price_bucket, product_id limit 3;
